"use client"

import * as React from "react"

import { IconSizeContext, useInk, useMergedRef } from "@/lib/ink/react"
import { kbdRecipe } from "@/lib/ink/recipes/kbd-ink"
import { cn } from "@/lib/utils"

function Kbd({
  className,
  seed,
  ref,
  ...props
}: React.ComponentProps<"kbd"> & {
  seed?: string | number
}) {
  const { hostRef, hostProps, node } = useInk({ recipe: kbdRecipe, params: {}, kind: "keycap", seed, still: true })
  const { children, ...rest } = props
  return (
    <IconSizeContext value={14}>
      <kbd
        data-slot="kbd"
        data-ink-sink="self"
        ref={useMergedRef<HTMLElement>(hostRef, ref)}
        {...hostProps}
        className={cn(
          "relative isolate inline-flex h-6 w-fit min-w-6 items-center justify-center gap-1 pr-[6.4px] pl-1 pb-[2.4px] font-hand text-sm leading-none font-normal whitespace-nowrap text-muted-foreground select-none",
          "transition-[translate] duration-(--ll-dur-press) ease-out active:translate-y-[1.6px] [&[data-pressed]:not([data-pressed=false])]:translate-y-[1.6px]",
          "[&_svg]:pointer-events-none [&_svg:not(.absolute):not([class*='size-'])]:size-3.5",
          "calm:h-5 calm:pr-1 calm:pb-0",
          "[[data-slot=tooltip-content]_&]:text-inherit",
          className
        )}
        {...rest}
      >
        {node}
        {children}
      </kbd>
    </IconSizeContext>
  )
}

function KbdGroup({ className, ...props }: React.ComponentProps<"kbd">) {
  return <kbd data-slot="kbd-group" className={cn("inline-flex items-center gap-1", className)} {...props} />
}

export { Kbd, KbdGroup }

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { box } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'

export const KEY_DEPTH = 2.4

export const kbdRecipe = defineRecipe<Record<string, never>>({
  id: 'kbd',
  kind: 'keycap',
  layers: ['rest'],
  pad: 12,
  draw(ink, { w, h }, _p, ctx) {
    const calm = ctx.calm
    const d = calm ? 0 : KEY_DEPTH
    const fw = w - d
    const fh = h - d
    const r = clamp(Math.min(fw, fh) * 0.16, 2, 3.4)
    ink.layer('rest', () => {
      if (!calm) ink.group({ part: 'depth', hideOn: 'pressed' }, () => ink.poly('wash', roundRectPoly(d, d, fw, fh, r), 'current', 0.3), 'under')
      ink.poly('under', roundRectPoly(0.5, 0.5, fw - 1, fh - 1, r), 'slip', 1)
      wash(ink, roundRectPoly(1.4, 1.4, fw - 2.8, fh - 2.8, r), 'current', { alpha: 0.09, material: 'wash' })
      box(ink, 0, 0, fw, fh, { pen: 'pencil', corner: r, loose: 0.6, opts: { color: 'current', width: 1, alpha: 0.85, simple: true } })
    })
  },
})
